type GameIcon = keyof typeof GAME_ICONS;

// sport / lotto are 21 px wide in the original, games / casino 20 px
const WIDE: GameIcon[] = ["sport", "sportDisabled", "lotto", "lottoDisabled"];

export function GameCategoryIcon({ icon }: { icon: GameIcon }) {
  const width = WIDE.includes(icon) ? 21 : 20;
  return (
    <svg width={width} height="20" viewBox={`0 0 ${width} 20`} fill="none" xmlns="http://www.w3.org/2000/svg" dangerouslySetInnerHTML={{ __html: GAME_ICONS[icon] }} />
  );
}
